// Clear any existing points
points.clear();

// Reserve space if possible (list doesn't support reserve, but we can hint)
for (const auto& coord : coords) {
    // Each coordinate vector must have at least 3 entries (x, y, z).
    // If only 2 entries are provided, assume z = 0.
    if (coord.size() < 2) {
        // Invalid entry, skip it.
        continue;
    }
    double x = coord[0];
    double y = coord[1];
    double z = (coord.size() >= 3) ? coord[2] : 0.0;

    // Construct the CGAL point and add it to the list.
    points.emplace_back(x, y, z);
}
